interface Rules { rules: Set<string>; wild: Set<string>; except: Set<string> }
let parsed: Rules | null = null;
function rules(): Rules {
  if (parsed) return parsed;
  const out: Rules = { rules: new Set(), wild: new Set(), except: new Set() };
  for (const line of gunzipSync(Buffer.from(PSL_GZ_BASE64, "base64")).toString("utf8").split("\n")) {
    if (!line) continue;
    if (line.startsWith("!")) out.except.add(line.slice(1));
    else if (line.startsWith("*.")) out.wild.add(line.slice(2));
    else out.rules.add(line);
  }
  parsed = out;
  return out;
}

/**
 * The registrable domain of a host (the public suffix plus one label), lower case; null when the host is itself a public suffix, an address, or has no dot. The PSL algorithm: the longest matching rule
 * wins, an exception rule removes its first label, and a name that no rule knows has a one-label suffix.
 */
export function registrableDomain(host: string): string | null {
  const h = host.trim().toLowerCase().replace(/\.$/u, "");
  if (!h || /^[0-9.]+$/.test(h) || h.includes(":")) return null;
  const labels = h.split(".");
  if (labels.length < 2 || labels.some((l) => l === "")) return null;
  const { rules: exact, wild, except } = rules();
  let suffixLen = 1; // the implicit "*" rule
  for (let i = 0; i < labels.length; i++) {
    const candidate = labels.slice(i).join(".");
    const len = labels.length - i;
    if (except.has(candidate)) { suffixLen = len - 1; break; }
    if (exact.has(candidate)) suffixLen = Math.max(suffixLen, len);
    if (len >= 2 && wild.has(labels.slice(i + 1).join("."))) suffixLen = Math.max(suffixLen, len);
  }
  return suffixLen >= labels.length ? null : labels.slice(labels.length - suffixLen - 1).join(".");
}

/** True when the two hosts have the same registrable domain (never true when either is itself a public suffix or an address). */
export function sameRegistrableDomain(a: string, b: string): boolean {
  const x = registrableDomain(a);
  return x !== null && x === registrableDomain(b);
}
